import re

_SKU_RE = re.compile(r"^([A-Z]{2,4}):(\d{4}):([A-Z])$")


def bulk_discount(qty):
    if qty >= 200:
        return 0.15
    if qty >= 25:
        return 0.05
    return 0.0


def line_total(unit_price, qty):
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


def parse_sku(s):
    if not isinstance(s, str):
        raise ValueError(f"invalid SKU: {s!r}")
    m = _SKU_RE.fullmatch(s)
    if not m:
        raise ValueError(f"invalid SKU: {s!r}")
    category, number, variant = m.groups()
    return {"category": category, "number": int(number), "variant": variant}

def shipping_zone(country_code):
    if country_code == "US":
        return 1
    if country_code in ("CA", "MX"):
        return 2
    return 3


_BASE = {1: 4.5, 2: 9.0, 3: 20.0}


def shipping_cost(weight_kg, zone):
    return round(_BASE[zone] + 1.2 * weight_kg, 2)


def is_oversize(l, w, h):
    return l > 120 or w > 120 or h > 120 or (l + w + h) > 300

